// Recusa cedo quem não manda token: não gasta chamada ao Supabase nem processa o corpo
const auth = String($input.first().json.headers?.authorization ?? '');
if (!/^Bearer\s+\S+/i.test(auth)) {
  throw new Error('Não autenticado');
}
return $input.all();

// Só o dono (definido no banco, função owner_check) pode acionar o pipeline
if ($input.first().json.is_owner !== true) {
  throw new Error('Não autorizado');
}
return [{ json: { body: $('Webhook Captura').first().json.body } }];

// Normaliza e classifica a entrada (link, texto ou arquivo) e escolhe a estratégia de extração
const body = $input.first().json.body || $input.first().json;
let url = body.url ? String(body.url).trim() : null;
let text = body.text ? String(body.text).trim() : null;
const hint = body.hint ? String(body.hint).trim() : null;
let fileBase64 = body.file_base64 || null;
const fileName = body.file_name ? String(body.file_name) : null;
let fileMime = body.file_mime ? String(body.file_mime).toLowerCase().split(';')[0].trim() : '';

// Texto que é só um link (ex.: compartilhado pelo celular) vira link
if (!url && text) {
  const m = text.match(/^(https?:\/\/\S+)$/i);
  if (m) { url = m[1]; text = null; }
}

const EXT_MIME = {
  pdf: 'application/pdf', txt: 'text/plain', md: 'text/markdown', csv: 'text/csv', json: 'application/json',
  png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp', heic: 'image/heic', heif: 'image/heif',
  mp3: 'audio/mpeg', wav: 'audio/wav', m4a: 'audio/mp4', aac: 'audio/aac', ogg: 'audio/ogg', flac: 'audio/flac',
  mp4: 'video/mp4', mov: 'video/quicktime', webm: 'video/webm', mpeg: 'video/mpeg', avi: 'video/avi', '3gp': 'video/3gpp'
};
if (fileBase64 && (!fileMime || fileMime === 'application/octet-stream') && fileName) {
  const ext = fileName.split('.').pop().toLowerCase();
  if (EXT_MIME[ext]) fileMime = EXT_MIME[ext];
}

const SOCIAL = /(^|\.)(instagram\.com|tiktok\.com|facebook\.com|fb\.watch|fb\.com|twitter\.com|x\.com|threads\.net|vimeo\.com|kwai\.com|pinterest\.[a-z.]+|reddit\.com|twitch\.tv|dailymotion\.com)$/i;
const YOUTUBE = /(^|\.)(youtube\.com|youtu\.be|youtube-nocookie\.com)$/i;

let strategy = 'text';
let sourceType = 'note';
if (fileBase64) {
  strategy = 'upload';
  if (fileMime.startsWith('audio/')) sourceType = 'audio';
  else if (fileMime === 'application/pdf') sourceType = 'pdf';
  else if (fileMime.startsWith('video/')) sourceType = 'reel';
  else sourceType = 'note';
} else if (url) {
  let host = '';
  // Sem new URL(): o sandbox do Code node do n8n não garante o construtor URL
  const hostMatch = url.match(/^https?:\/\/(?:[^\/?#@]*@)?([^\/?#:]+)/i);
  host = hostMatch ? hostMatch[1].toLowerCase() : '';
  if (YOUTUBE.test(host)) { strategy = 'youtube'; sourceType = 'youtube'; }
  else if (SOCIAL.test(host)) { strategy = 'social'; sourceType = 'reel'; }
  else { strategy = 'web'; sourceType = 'article'; }
}

return [{
  json: {
    url, text, hint, fileBase64, fileMime, fileName, strategy, sourceType,
    rawInput: url || text || fileName || 'Arquivo recebido'
  }
}];

// Extrai o JSON do Gemini; em qualquer falha devolve um item de caixa de entrada com aviso claro
const ctx = $('Montar Requisição Gemini').first().json;
const res = $input.first().json;
const problems = [...ctx.warnings];

function tryParse(raw) {
  const cleaned = String(raw).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(cleaned); } catch (e) { /* tenta recortar o objeto */ }
  const a = cleaned.indexOf('{');
  const b = cleaned.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(cleaned.slice(a, b + 1)); } catch (e) { return null; } }
  return null;
}

let parsed = null;
let rawText = '';
function describeGeminiError(err) {
  const raw = String(err.message || err.description || JSON.stringify(err));
  const status = Number(err.httpCode || (raw.match(/^(\d{3})\b/) || [])[1] || 0);
  if (status === 429 || /RESOURCE_EXHAUSTED|quota/i.test(raw)) return 'a IA atingiu o limite de uso por agora';
  if (status === 408 || status >= 500 || /UNAVAILABLE|high demand|overloaded|timed? ?out|ECONNRESET|ETIMEDOUT/i.test(raw)) return 'a IA está sobrecarregada ou fora do ar no momento';
  if (status === 401 || status === 403) return 'a IA recusou o acesso (verifique a chave do Gemini)';
  return 'a IA não aceitou o pedido' + (status ? ' (HTTP ' + status + ')' : '');
}

if (res && res.error) {
  problems.push('Falha no Gemini: ' + describeGeminiError(res.error) + '. Use "Reprocessar" para tentar de novo.');
} else {
  const cand = res && res.candidates && res.candidates[0];
  rawText = (cand && cand.content && cand.content.parts || []).map(p => p.text || '').join('');
  if (!rawText) {
    const why = (res && res.promptFeedback && res.promptFeedback.blockReason) || (cand && cand.finishReason) || 'resposta vazia';
    problems.push('O Gemini não retornou análise (' + why + ').');
  } else {
    parsed = tryParse(rawText);
    if (!parsed) problems.push('A resposta do Gemini veio incompleta; conteúdo salvo sem estruturação.');
  }
}

const list = v => (Array.isArray(v) ? v.map(String) : []);
const analyzed = !!parsed && parsed.content_accessible !== false;
if (parsed && parsed.content_accessible === false) problems.push('O conteúdo do link não estava acessível à IA.');

const fallbackTitle = ctx.meta.title || ctx.hint || (ctx.url ? ctx.url.replace(/^https?:\/\//, '').slice(0, 60) : 'Captura ' + new Date().toLocaleDateString('pt-BR'));
const p = parsed || {};
const title = p.title || fallbackTitle;
const summary = p.summary || (problems.length ? 'Sem análise automática: ' + problems.join(' ') : '');
const tags = list(p.tags).length ? list(p.tags) : ['inbox'];
if (!analyzed && !tags.includes('inbox')) tags.push('inbox');
const bodyText = p.raw_content || (parsed ? '' : rawText) || ctx.meta.description || '';
const rawContent = ctx.fileName ? 'Conteúdo extraído do arquivo "' + ctx.fileName + '" (o arquivo original não é armazenado).' + String.fromCharCode(10, 10) + bodyText : bodyText;
const takeaways = list(p.key_takeaways);
const entities = list(p.entities);
const clip = (v, max) => (typeof v === 'string' ? v.replace(/\s+/g, ' ').trim().slice(0, max) : '');
// Links de origem (repositório/site) anexados à nota: vindos do Gemini, da página e do texto capturado
const REPO_HOSTS = /^(?:www\.)?(github\.com|gitlab\.com|bitbucket\.org|codeberg\.org|huggingface\.co|git\.sr\.ht|sr\.ht)$/i;
function cleanUrl(v) {
  const m = String(v || '').trim().match(/^(https?:\/\/[^\s<>"'`]+)/i);
  return m ? m[1].replace(/[)\].,;:!?*_]+$/, '') : '';
}
function linkKey(u) {
  return u.toLowerCase().replace(/#.*$/, '').replace(/[?&](utm_[a-z]+|igsh|igshid|si|fbclid)=[^&]*/g, '').replace(/\/+$/, '');
}
function linkKind(u, hinted) {
  const m = u.match(/^https?:\/\/(?:[^@\/]*@)?([^\/:?#]+)(?::\d+)?\/?([^?#]*)/i);
  if (m && REPO_HOSTS.test(m[1]) && m[2].split('/').filter(Boolean).length >= 2) return 'repo';
  return hinted === 'repo' ? 'repo' : 'site';
}
const originLinks = [];
function addLink(url, hinted, label) {
  const u = cleanUrl(url);
  if (!u || u.length > 500 || originLinks.length >= 10) return;
  const key = linkKey(u);
  if (originLinks.some(l => linkKey(l.url) === key)) return;
  originLinks.push({ url: u, kind: linkKind(u, hinted), label: clip(label, 80) || null });
}
const examples = [];
for (const e of (Array.isArray(p.practical_examples) ? p.practical_examples : [])) {
  if (!e || typeof e !== 'object') continue;
  const ex = { title: clip(e.title, 120), scenario: clip(e.scenario, 300), how: clip(e.how, 700), uses: [] };
  if (!ex.title || !ex.how || examples.some(x => x.title.toLowerCase() === ex.title.toLowerCase())) continue;
  examples.push(ex);
  if (examples.length === 5) break;
}

if (ctx.url && (ctx.sourceType === 'article' || linkKind(cleanUrl(ctx.url), '') === 'repo')) addLink(ctx.url, '', ctx.meta.title);
if (ctx.meta.canonical && ctx.sourceType === 'article') addLink(ctx.meta.canonical, '', ctx.meta.title);
for (const l of (Array.isArray(p.origin_links) ? p.origin_links : [])) {
  if (typeof l === 'string') addLink(l, '', '');
  else if (l && typeof l === 'object') addLink(l.url, l.kind === 'repo' ? 'repo' : '', l.label);
}
const ownKey = ctx.url ? linkKey(cleanUrl(ctx.url)) : '';
for (const found of (String(ctx.meta.description || '') + '\n' + String(rawContent) + '\n' + summary).match(/https?:\/\/[^\s<>"'`]+/gi) || []) {
  if (linkKey(cleanUrl(found)) !== ownKey) addLink(found, '', '');
}

const embedText = [title, summary, takeaways.join('. '), tags.join(' '), entities.join(' '), String(rawContent).slice(0, 4000)]
  .filter(Boolean).join('\n');

return [{
  json: {
    title,
    summary,
    key_takeaways: takeaways,
    practical_examples: examples,
    entities,
    raw_content: String(rawContent),
    tags,
    stage: 'budding',
    source_type: ctx.sourceType,
    source_url: ctx.url,
    text_for_embedding: embedText,
    analysis_ok: analyzed,
    warnings: problems,
    metadata: { analysis_ok: analyzed, warnings: problems, author: ctx.meta.uploader || null, extracted_from_file: ctx.fileName || null, origin_links: originLinks }
  }
}];

